import { after } from 'next/server'

type PageViewEvent = {
  path: string
  timestamp: number
  userAgent: string | null
}

async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT
  if (!endpoint) {
    console.log('[analytics] page view', event)
    return
  }

  await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(event),
  })
}

export default async function Home() {
  after(async () => {
    await logPageView({
      path: '/',
      timestamp: Date.now(),
      userAgent: null,
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Glad to have you here.</p>
    </main>
  )
}
